import string
from solution import check_if_last_char_is_a_letter as f
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _ref(txt):
    # Obviously-correct reference derived from spec:
    # word = group separated by literal space ' '.
    # True iff last char is ASCII letter and forms a single-char last word.
    if len(txt) == 0:
        return False
    last = txt[-1]
    if last not in string.ascii_letters:
        return False
    if len(txt) == 1:
        return True
    # last char is letter; isolated iff previous char is space
    # (equivalently txt.split(' ')[-1] has length 1)
    return txt[-2] == " "


# ---- explicit spec examples ----
def test_spec_apple_pie_false():
    assert f("apple pie") is False


def test_spec_apple_pi_e_true():
    assert f("apple pi e") is True


def test_spec_trailing_space_false():
    assert f("apple pi e ") is False


def test_spec_empty_false():
    assert f("") is False


def test_single_letter_is_true():
    assert f("a") is True
    assert f("Z") is True


def test_single_letter_with_leading_space_true():
    assert f(" a") is True
    assert f("  b") is True


def test_uppercase_isolated_true():
    assert f("apple pi E") is True


def test_last_word_longer_than_one_false():
    assert f("apple pie") is False
    assert f("ab") is False
    assert f("a bc") is False
    assert f("a bcd") is False


def test_trailing_space_always_false():
    assert f("e ") is False
    assert f("a b ") is False
    assert f(" ") is False
    assert f("  ") is False
    assert f("apple pi e  ") is False


def test_last_char_non_alpha_false():
    assert f("apple pi 1") is False
    assert f("apple pi !") is False
    assert f("apple pi e!") is False
    assert f("a 1") is False
    assert f("a _") is False
    assert f("a.") is False
    assert f("123") is False


def test_tab_does_not_separate_words():
    # SPEC: word is group separated by space, so tab is part of word.
    # "apple\te" is one word -> last char part of word -> False
    assert f("apple\te") is False
    assert f("a\tb") is False
    assert f("a\t e") is True  # last word after space is isolated 'e'
    assert f("a\te") is False


def test_newline_does_not_separate_words():
    assert f("apple\ne") is False
    assert f("a\nb") is False
    assert f("a\n e") is True


def test_carriage_return_does_not_separate():
    assert f("a\rb") is False


def test_unicode_letter_not_ascii_false():
    # alphabetical in spec examples is a-z; non-ascii should not count
    assert f("apple pi \u00e9") is False
    assert f("\u00e9") is False
    assert f("a \u00e9") is False


# ---- property-based tests ----

@given(st.text(alphabet=st.sampled_from(list(string.ascii_letters + " ")), min_size=0, max_size=20))
def test_property_agrees_with_space_split_reference(txt):
    assert f(txt) is _ref(txt)


@given(st.text(alphabet=st.sampled_from(list(string.ascii_letters + " \t\n\r")), min_size=0, max_size=20))
def test_property_agrees_with_reference_including_whitespace(txt):
    # tabs/newlines are NOT separators per spec
    assert f(txt) is _ref(txt)


@given(st.text(alphabet=st.sampled_from(list(string.ascii_letters + " ")), min_size=1, max_size=20).filter(lambda s: len(s) > 0 and s[-1] not in string.ascii_letters))
def test_property_last_char_non_alpha_implies_false(txt):
    assert f(txt) is False


@given(
    st.text(alphabet=st.sampled_from(list(string.ascii_letters)), min_size=2, max_size=10),
    st.text(alphabet=st.sampled_from(list(string.ascii_letters + " ")), min_size=0, max_size=10),
)
def test_property_last_word_len_gt1_implies_false(last_word, prefix):
    assume(len(last_word) > 1)
    assume(all(c != " " for c in last_word))
    txt = (prefix + " " + last_word) if prefix else last_word
    # ensure no trailing space and last word really is last_word
    assume(not txt.endswith(" "))
    assert f(txt) is False


@given(
    st.text(alphabet=st.sampled_from(list(string.ascii_letters + " ")), min_size=0, max_size=10),
    st.sampled_from(list(string.ascii_letters)),
)
def test_property_isolated_letter_after_space_implies_true(prefix, letter):
    # build txt ending with " <letter>" with no trailing space
    assume(not prefix.endswith(" "))
    if prefix == "":
        txt = letter
    else:
        # force prefix to end with non-space content or be empty-ish; just append space+letter
        txt = prefix.rstrip(" ") + " " + letter if prefix.strip(" ") != "" else " " + letter
    assert f(txt) is True


@given(st.sampled_from(list(string.ascii_letters)))
def test_property_single_ascii_letter_true(letter):
    assert f(letter) is True


@given(st.text(alphabet=st.sampled_from(list(string.ascii_letters + " ")), min_size=0, max_size=10))
def test_property_trailing_space_implies_false(prefix):
    assume(prefix != "")
    txt = prefix + " "
    assert f(txt) is False
